package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * The single definition of address normalization, applied when an owner is created
 * (see {@link NormalizeOwnerAddress}) so that the stored and returned address is in one
 * canonical form.
 *
 * <p>Normalization trims and collapses whitespace runs to a single space, upper-cases the
 * value, and expands the common street-type abbreviations {@code ST->STREET},
 * {@code RD->ROAD} and {@code AVE->AVENUE} (matched as whole space-separated tokens).
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    /**
     * Normalize an address to its canonical stored/compared form. A {@code null} or
     * blank input yields the empty string.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder result = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            String token = tokens[i].toUpperCase(Locale.ROOT);
            token = ABBREVIATIONS.getOrDefault(token, token);
            if (i > 0) {
                result.append(' ');
            }
            result.append(token);
        }
        return result.toString();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.BlankAddressException;

/**
 * Normalizes the address on create: trims and collapses whitespace, upper-cases, and
 * expands the common street-type abbreviations (see {@link AddressNormalizer}). The
 * normalized value is stored back on the request so later steps build, compare, save and
 * return it. The required-field check runs against the normalized form: an address that is
 * blank after normalization is rejected 400 via {@link BlankAddressException}.
 */
public class NormalizeOwnerAddress {

    public void service(@Val OwnerFieldsDto request) throws BlankAddressException {
        String raw = request.getAddress();
        String normalized = AddressNormalizer.normalize(raw);
        if (normalized.isEmpty()) {
            throw new BlankAddressException(raw);
        }
        request.setAddress(normalized);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of household identity, used by {@link AssignOwnerHousehold} (which
 * stamps the householdId) and by the household-keyed rules (duplicate detection, household
 * size), so the rule lives in one place.
 *
 * <p>A household is keyed on {@code (lastName, postcode)}: two owners are in the same
 * household when their normalized lastName and postcode match. The householdId is therefore
 * <em>deterministic</em> — the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode} — so owners with the same lastName and
 * postcode share it automatically, with no lookup. lastName is normalized case-insensitively
 * with collapsed whitespace; the postcode is used as given (empty when absent).
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /**
     * The deterministic householdId for the given lastName and postcode: the first 12 hex
     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners with the
     * same lastName and postcode therefore compute the same householdId automatically.
     */
    static String householdId(String lastName, String postcode) {
        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        return sha256Hex(input).substring(0, 12);
    }

    /**
     * The number of owners in the given household — those whose {@code householdId} matches.
     * A {@code null} householdId matches nothing. Used by the household-keyed rules so the
     * membership comparison lives in the same place as the identity that defines it.
     */
    static int memberCount(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return 0;
        }
        int count = 0;
        for (Owner owner : owners) {
            if (householdId.equals(owner.getHouseholdId())) {
                count++;
            }
        }
        return count;
    }

    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
                sb.append(Character.forDigit(b & 0xF, 16));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** Lower-case and collapse whitespace runs to a single space for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.CityRegions;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the owner's postcode against the city's region, but only WHEN PRESENT — a
 * request with no postcode passes through unchanged (the create/update contract stays
 * backward-compatible). Its 4-digit shape is already enforced by the {@code OwnerFields}
 * schema pattern; this step applies the region-specific range rule. For a city with a known
 * region (Sydney=NSW 2000-2099, Melbourne=VIC 3000-3099, Brisbane=QLD 4000-4099) the postcode
 * must fall within that region's inclusive range; a city with no known region accepts any
 * 4-digit postcode. An out-of-range postcode is rejected 400 via {@link InvalidPostcodeException}.
 */
public class EnsurePostcodeValidForCity {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isEmpty()) {
            return; // optional: validated only when present
        }
        String region = CityRegions.regionOf(request.getCity());
        if (region == null) {
            return; // city has no known region -> any 4-digit postcode is accepted
        }
        int[] range = CityRegions.postcodeRange(region); // single shared source of the range fact
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(request.getCity(), postcode);
        }
    }
}
